import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import {
  Search,
  Calendar,
  RefreshCw,
  Download,
  FileText,
  Eye,
  CheckCircle,
  AlertCircle
} from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { isDarkMode, addThemeChangeListener } from '../../utils/themeUtils';
import { getPayrollRecordsForPeriod, getPayrollRecord, markPayslipPrinted, calculatePayrollFromFirebase } from '../../services/payrollService';
import { payslipService } from '../../services/payslipService';
import useAuth from '../../contexts/authcontext';

// Minimal local helpers and placeholders so the component compiles.
const formatCurrency = (v) => (typeof v === 'number' ? '₱' + v.toLocaleString() : (v ? String(v) : '₱0'));
const formatDeductionLabel = (k) => k;

const PayslipViewer = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPeriod, setSelectedPeriod] = useState(new Date().toISOString().slice(0, 7));
  const [filteredPayslips, setFilteredPayslips] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [selectedPayslip, setSelectedPayslip] = useState(null);
  const printRef = useRef();
  const { user } = useAuth();

  const loadPayrollRecords = async (period) => {
    setLoading(true);
    try {
      const periodToLoad = period || selectedPeriod;
      // If a user is present, fetch only their payslips so employees see only their own records
      const viewerId = (window.currentUser && (window.currentUser.facultyId || window.currentUser.userId || window.currentUser.uid)) || (user && (user.facultyId || user.userId || user.uid)) || null;
      const records = await getPayrollRecordsForPeriod(periodToLoad, viewerId);
      setFilteredPayslips(records || []);
    } catch (err) {
      console.error('Failed to load payroll records', err);
      setFilteredPayslips([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const wrapped = async () => {
      await loadPayrollRecords(selectedPeriod);
      // If no stored records and a user context exists, try compute-on-the-fly for the current user
      try {
        if ((filteredPayslips || []).length === 0 && window.currentUser && window.currentUser.uid) {
          // attempt to compute a payroll for the current user
          const id = window.currentUser.facultyId || window.currentUser.userId || window.currentUser.uid;
          if (id) {
            try {
              const grossSalary = window.currentUser.salaryInfo?.salaryRate || window.currentUser.salaryRate || 0;
              const computed = await calculatePayrollFromFirebase(id, selectedPeriod, grossSalary);
              setFilteredPayslips([{
                ...computed,
                id,
                facultyName: window.currentUser.name || window.currentUser.displayName || window.currentUser.email,
                facultyId: id,
              }]);
            } catch (err) {
              // ignore compute failures here; UI will show 'No payslips'
            }
          }
        }
      } catch (e) {}
    };
    wrapped();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPeriod]);

  const handleViewPayslip = async (p) => {
    // Try to fetch fresh record from DB (may include latest audit fields)
    const period = selectedPeriod;
    const id = p.facultyId || p.userId || p.id;
    try {
      const record = await getPayrollRecord(id, period);
      if (record) {
        // Build printable payslip HTML and open in a new window so employees see the same printable template
        const facultyProfile = {
          name: p.facultyName || p.name || record.employeeInfo?.name || '',
          employeeId: p.facultyId || p.userId || p.id,
          position: p.position || record.employeeInfo?.position || '',
          department: p.department || record.employeeInfo?.department || ''
        };
        const payrollWithHr = { ...record };
        if (user && user.name) payrollWithHr.hrName = user.name;
        const html = payslipService.buildPrintablePayslipHtml(payrollWithHr, facultyProfile);
        const w = window.open('', '_blank');
        if (w) {
          w.document.open();
          w.document.write(html);
          w.document.close();
          w.focus();
        } else {
          alert('Popup blocked: enable popups to preview payslip');
        }
        return;
      }
      // If no stored payroll record found, attempt to compute from Firebase data
      try {
        const grossSalary = p.grossSalary || p.breakdown?.salaryRate || p.salaryRate || 0;
        const computed = await calculatePayrollFromFirebase(id, period, grossSalary);
        const facultyProfile = {
          name: p.facultyName || p.name || computed.employeeInfo?.name || '',
          employeeId: p.facultyId || p.userId || p.id,
          position: p.position || computed.employeeInfo?.position || '',
          department: p.department || computed.employeeInfo?.department || ''
        };
        const payrollWithHr = { ...computed };
        if (user && user.name) payrollWithHr.hrName = user.name;
        const html = payslipService.buildPrintablePayslipHtml(payrollWithHr, facultyProfile);
        const w = window.open('', '_blank');
        if (w) {
          w.document.open();
          w.document.write(html);
          w.document.close();
          w.focus();
        } else {
          alert('Popup blocked: enable popups to preview payslip');
        }
        return;
      } catch (computeErr) {
        // fallback to showing passed object
        console.warn('Failed to compute payroll fallback', computeErr);
        const facultyProfile = {
          name: p.facultyName || p.name || p.employeeInfo?.name || '',
          employeeId: p.facultyId || p.userId || p.id,
          position: p.position || p.employeeInfo?.position || '',
          department: p.department || p.employeeInfo?.department || ''
        };
        const payrollWithHr = { ...p };
        if (user && user.name) payrollWithHr.hrName = user.name;
        const html = payslipService.buildPrintablePayslipHtml(payrollWithHr, facultyProfile);
        const w = window.open('', '_blank');
        if (w) {
          w.document.open();
          w.document.write(html);
          w.document.close();
          w.focus();
        } else {
          alert('Popup blocked: enable popups to preview payslip');
        }
      }
    } catch (err) {
      console.error('Failed to fetch payroll record', err);
      const facultyProfile = {
        name: p.facultyName || p.name || p.employeeInfo?.name || '',
        employeeId: p.facultyId || p.userId || p.id,
        position: p.position || p.employeeInfo?.position || '',
        department: p.department || p.employeeInfo?.department || ''
      };
      const payrollWithHr = { ...p };
      if (user && user.name) payrollWithHr.hrName = user.name;
      const html = payslipService.buildPrintablePayslipHtml(payrollWithHr, facultyProfile);
      const w = window.open('', '_blank');
      if (w) {
        w.document.open();
        w.document.write(html);
        w.document.close();
        w.focus();
      } else {
        alert('Popup blocked: enable popups to preview payslip');
      }
    }
  };

  const handlePrintPayslip = async (p) => {
    try {
      const period = selectedPeriod;
      const id = p.facultyId || p.userId || p.id;
      // mark printed for audit
      await markPayslipPrinted(id, period);
      // refresh list so lastPrintedAt appears
      await loadPayrollRecords(period);
      // open printable window using the white payslip template
      const facultyProfile = {
        name: p.facultyName || p.name || '',
        employeeId: p.facultyId || p.userId || p.id,
        position: p.position || p.employeeInfo?.position || '',
        department: p.department || p.employeeInfo?.department || ''
      };
      const payrollWithHr = { ...p };
      if (user && user.name) payrollWithHr.hrName = user.name;
      const html = payslipService.buildPrintablePayslipHtml(payrollWithHr, facultyProfile);
      const w = window.open('', '_blank');
      if (w) {
        w.document.open();
        w.document.write(html);
        w.document.close();
        // allow the new window to render before printing
        w.focus();
      } else {
        alert('Popup blocked: enable popups to print payslip');
      }
    } catch (err) {
      console.error('Failed to mark printed', err);
      alert('Failed to record printed audit.');
    }
  };

  // Download or export a payslip. Uses centralized payslipService where possible.
  const handleDownloadPayslip = async (p, type) => {
    try {
      const facultyProfile = {
        name: p.facultyName || p.name || '',
        employeeId: p.facultyId || p.userId || p.id,
        position: p.position || p.employeeInfo?.position || '',
        department: p.department || p.employeeInfo?.department || ''
      };


      const payrollWithHr = { ...p };
      if (user && user.name) payrollWithHr.hrName = user.name;

      if (type === 'pdf') {
        // Use centralized PDF generator & download helper
        await payslipService.downloadPayslipPDF(payrollWithHr, facultyProfile);
        return;
      }

      if (type === 'excel' || type === 'csv') {
        // Use centralized Excel/CSV generator
        await payslipService.downloadPayslipExcel(payrollWithHr, facultyProfile);
        return;
      }

      // Fallback: simple CSV export of object fields
      const rows = [];
      rows.push(['Field', 'Value']);
      Object.entries(p || {}).forEach(([k, v]) => rows.push([k, typeof v === 'object' ? JSON.stringify(v) : String(v)]));
      const csv = rows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(',')).join('\n');
      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `payslip-${p.id || (p.facultyId || p.userId)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Failed to download payslip', err);
      alert('Failed to download payslip.');
    }
  };

  const getStatusBadge = (status) => {
    if (!status) return (<span className="px-2 py-1 text-xs font-medium bg-gray-100 text-gray-800 rounded-full">Unknown</span>);
    switch (status) {
      case 'processed':
        return (<span className="px-2 py-1 text-xs font-medium bg-green-100 text-green-800 rounded-full">Processed</span>);
      case 'pending':
      case 'processing':
        return (<span className="px-2 py-1 text-xs font-medium bg-yellow-100 text-yellow-800 rounded-full">Pending</span>);
      default:
        return (<span className="px-2 py-1 text-xs font-medium bg-red-100 text-red-800 rounded-full">Error</span>);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-8"
        >
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            Payslip Viewer
          </h1>
          <p className="text-gray-600">
            View and download your payslips
          </p>
        </motion.div>

        {/* Search and Filter */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-lg shadow-md p-6 mb-8"
        >
          <div className="flex flex-col md:flex-row md:items-center md:justify-between space-y-4 md:space-y-0">
            <div className="flex-1 max-w-md">
              <div className="relative">
                <Search className="h-5 w-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search by name or employee ID..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-2">
                <Calendar className="h-4 w-4 text-gray-400" />
                <input
                  type="month"
                  value={selectedPeriod}
                  onChange={(e) => setSelectedPeriod(e.target.value)}
                  className="px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <button
                onClick={() => {
                  setSearchTerm('');
                  setSelectedPeriod('');
                }}
                className="px-4 py-2 text-gray-600 hover:text-gray-800 flex items-center space-x-2"
              >
                <RefreshCw className="h-4 w-4" />
                <span>Clear</span>
              </button>
            </div>
          </div>
        </motion.div>

        {/* Payslips Table */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow-md overflow-hidden"
        >
          <div className="px-6 py-4 border-b border-gray-200">
            <h3 className="text-lg font-semibold text-gray-900">
              Payslips ({filteredPayslips.length})
            </h3>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Pay Period
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Employee
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Gross Pay
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Net Pay
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {filteredPayslips.map((payslip, index) => (
                  <motion.tr
                    key={payslip.id || payslip.facultyId || payslip.userId || index}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.1 * index }}
                    className="hover:bg-gray-50"
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-gray-900">
                        {payslip.periodStart ? (() => { try { return format(parseISO(payslip.periodStart), 'MMM yyyy'); } catch (e) { return payslip.periodStart; }})() : '—'}
                      </div>
                      <div className="text-xs text-gray-500">
                        {payslip.periodStart ? (() => { try { return format(parseISO(payslip.periodStart), 'dd'); } catch (e) { return ''; }})() : ''} - {payslip.periodEnd ? (() => { try { return format(parseISO(payslip.periodEnd), 'dd'); } catch (e) { return ''; }})() : ''}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div>
                          <div className="text-sm font-medium text-gray-900">
                            {payslip.facultyName}
                          </div>
                          <div className="text-sm text-gray-500">
                            {payslip.employeeId}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {formatCurrency(payslip.grossSalary || 0)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {formatCurrency(payslip.netSalary || 0)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(payslip.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button
                        onClick={() => handleViewPayslip(payslip)}
                        className="text-blue-600 hover:text-blue-900 mr-3 flex items-center space-x-1"
                      >
                        <Eye className="h-4 w-4" />
                        <span>View</span>
                      </button>
                      <button
                        onClick={() => handleDownloadPayslip(payslip, 'excel')}
                        className="text-purple-600 hover:text-purple-900 flex items-center space-x-1"
                      >
                        <FileText className="h-4 w-4" />
                        <span>Excel</span>
                      </button>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>

          {filteredPayslips.length === 0 && (
            <div className="text-center py-12">
              <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">
                No payslips found
              </h3>
              <p className="text-gray-500">
                {searchTerm || selectedPeriod
                  ? 'Try adjusting your search criteria'
                  : 'No payslips available for the selected period'
                }
              </p>
            </div>
          )}
        </motion.div>

        {/* Quick Stats */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6"
        >
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Total Payslips</p>
                <p className="text-2xl font-bold text-gray-900">
                  {filteredPayslips.length}
                </p>
              </div>
              <FileText className="h-8 w-8 text-blue-500" />
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Processed</p>
                <p className="text-2xl font-bold text-green-600">
                  {filteredPayslips.filter(p => p.status === 'processed').length}
                </p>
              </div>
              <CheckCircle className="h-8 w-8 text-green-500" />
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Pending</p>
                <p className="text-2xl font-bold text-yellow-600">
                  {filteredPayslips.filter(p => p.status === 'processing' || p.status === 'pending').length}
                </p>
              </div>
              <AlertCircle className="h-8 w-8 text-yellow-500" />
            </div>
          </div>
        </motion.div>
      </div>

      {/* Payslip Preview Modal */}
      {showPreview && selectedPayslip && (
        <PayslipPreview
          payslip={selectedPayslip}
          onClose={() => {
            setShowPreview(false);
            setSelectedPayslip(null);
          }}
          printRef={printRef}
          handlePrintPayslip={handlePrintPayslip}
          handleDownloadPayslip={handleDownloadPayslip}
        />
      )}
    </div>
  );
};

export default PayslipViewer;

// Simple PayslipPreview component used by PayslipViewer modal
const PayslipPreview = ({ payslip, onClose, printRef, handlePrintPayslip, handleDownloadPayslip }) => {
  if (!payslip) return null;
  const [isDark, setIsDark] = useState(() => isDarkMode());
  useEffect(() => {
    const cleanup = addThemeChangeListener((d) => setIsDark(d));
    return cleanup;
  }, []);

  const gross = Number(payslip.grossSalary || payslip.breakdown?.salaryRate || 0);
  const net = Number(payslip.netSalary || 0);
  const totalDeductions = (payslip.deductions && payslip.deductions.total) || payslip.breakdown?.totalDeductions || 0;
  const totalAllowances = (payslip.allowances && payslip.allowances.total) || payslip.breakdown?.totalAllowances || 0;
  const otherPayablesTotal = payslip.otherPayablesTotal || payslip.otherPayables || 0;

  const modalBgClass = isDark ? 'bg-slate-900 text-gray-100' : 'bg-white text-gray-900';
  const panelClass = isDark ? 'bg-slate-800 text-gray-100' : 'bg-gray-50 text-gray-900 border border-gray-200';
  const cardBase = 'rounded-md p-4 text-center';
  const cardBorder = isDark ? 'border-transparent' : 'border-gray-200';
  const greenCardClass = isDark ? `${cardBase} bg-green-700 text-green-100 border ${cardBorder}` : `${cardBase} bg-white text-green-800 border border-green-100`;
  const redCardClass = isDark ? `${cardBase} bg-red-600 text-red-100 border ${cardBorder}` : `${cardBase} bg-white text-red-800 border border-red-100`;
  const blueCardClass = isDark ? `${cardBase} bg-blue-700 text-blue-100 border ${cardBorder}` : `${cardBase} bg-white text-blue-800 border border-blue-100`;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.98, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.98, opacity: 0 }}
        className={`${modalBgClass} rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-xl`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-6">
          <div className="flex items-start justify-between mb-6">
            <div style={{ flex: 1 }} />
            <div style={{ flex: 2, textAlign: 'center' }}>
              <h3 className="text-2xl font-bold">Fingerprint Attendance System Tracking and Payroll</h3>
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-600'}`}>Human Resources Department • Payroll Management System</div>
            </div>
            <div style={{ flex: 1, textAlign: 'right' }}>
              <button onClick={onClose} className={`${isDark ? 'text-slate-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}`}>×</button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            <div className="space-y-2">
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'}`}>Employee Name:</div>
              <div className="text-lg font-semibold">{payslip.facultyName || payslip.employeeInfo?.name || '—'}</div>
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'} mt-3`}>Position:</div>
              <div>{payslip.position || payslip.employeeInfo?.salaryInfo?.position || '—'}</div>
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'} mt-3`}>Salary Grade/Step:</div>
              <div>{payslip.salaryGrade || '—'}</div>
            </div>
            <div className="space-y-2 text-right">
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'}`}>Employee ID:</div>
              <div className="text-lg font-semibold">{payslip.employeeId || payslip.id}</div>
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'} mt-3`}>Employment Status:</div>
              <div>{payslip.employmentStatus || '—'}</div>
              <div className={`text-sm ${isDark ? 'text-slate-400' : 'text-gray-500'} mt-3`}>Pay Period:</div>
              <div>{payslip.periodStart ? format(parseISO(payslip.periodStart), 'MMM dd, yyyy') : ''} - {payslip.periodEnd ? format(parseISO(payslip.periodEnd), 'MMM dd, yyyy') : ''}</div>
            </div>
          </div>

          <div className="flex gap-4 mb-6">
            <div className={`flex-1 ${greenCardClass}`}>
              <div className="text-sm">Gross Pay</div>
              <div className="text-2xl font-bold">{formatCurrency(gross)}</div>
            </div>
            <div className={`flex-1 ${redCardClass}`}>
              <div className="text-sm">Total Deductions</div>
              <div className="text-2xl font-bold">{formatCurrency(totalDeductions)}</div>
            </div>
            <div className={`flex-1 ${blueCardClass}`}>
              <div className="text-sm">Net Pay</div>
              <div className="text-2xl font-bold">{formatCurrency(net)}</div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className={`${panelClass} p-4 rounded-md`}>
              <h4 className="font-semibold mb-2">Earnings</h4>
              <table className={`${isDark ? 'text-gray-200' : 'text-gray-800'} w-full`}>
                <tbody>
                  {payslip.breakdown?.isHourly ? (
                    <>
                      <tr>
                        <td colSpan="2" className="pb-2">
                          <div className="text-sm font-medium mb-1">Hourly Breakdown:</div>
                          <div className="text-xs text-gray-500">Regular Hours: {payslip.breakdown.totalHours} hrs @ ₱{payslip.breakdown.baseRate}/hr</div>
                          {payslip.breakdown.totalOvertime > 0 && (
                            <div className="text-xs text-gray-500">Overtime: {payslip.breakdown.totalOvertime} hrs @ ₱{payslip.breakdown.overtimeRate}/hr</div>
                          )}
                          {payslip.breakdown.lateCount > 0 && (
                            <div className="text-xs text-gray-500">Late Days: {payslip.breakdown.lateCount} @ ₱{payslip.breakdown.lateDeduction}/incident</div>
                          )}
                        </td>
                      </tr>
                      <tr><td>Regular Hours Pay</td><td className="text-right">{formatCurrency(payslip.breakdown.baseEarnings)}</td></tr>
                      {payslip.breakdown.overtimeEarnings > 0 && (
                        <tr><td>Overtime Pay</td><td className="text-right">{formatCurrency(payslip.breakdown.overtimeEarnings)}</td></tr>
                      )}
                      {payslip.breakdown.totalLateDeductions > 0 && (
                        <tr><td>Late Deductions</td><td className="text-right text-red-500">-{formatCurrency(payslip.breakdown.totalLateDeductions)}</td></tr>
                      )}
                    </>
                  ) : (
                    <tr><td>Basic Salary</td><td className="text-right">{formatCurrency(payslip.grossSalary || payslip.breakdown?.salaryRate)}</td></tr>
                  )}
                  <tr><td>Adjustments</td><td className="text-right">{formatCurrency(payslip.adjustment || 0)}</td></tr>
                  <tr><td>Allowances</td><td className="text-right">{formatCurrency(totalAllowances)}</td></tr>
                  <tr className="border-t pt-2"><td className="font-semibold">Total Earnings</td><td className="text-right font-semibold">{formatCurrency((gross || 0) + (payslip.adjustment || 0) + (totalAllowances || 0) + (payslip.breakdown?.serviceCredits || 0))}</td></tr>
                </tbody>
              </table>
            </div>
            <div className={`${panelClass} p-4 rounded-md`}>
              <h4 className="font-semibold mb-2">Deductions</h4>
              <table className={`${isDark ? 'text-gray-200' : 'text-gray-800'} w-full`}>
                <tbody>
                  {payslip.deductions && Object.entries(payslip.deductions).filter(([k]) => k !== 'total').map(([k,v]) => (
                    <tr key={k}><td>{formatDeductionLabel(k)}</td><td className="text-right">{formatCurrency(v)}</td></tr>
                  ))}
                  <tr className="border-t pt-2"><td className="font-semibold">Total Deductions</td><td className="text-right font-semibold">{formatCurrency(totalDeductions)}</td></tr>
                </tbody>
              </table>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6">
            <div className={`${panelClass} p-4 rounded-md`}>
              <h4 className="font-semibold mb-2">Other Payables</h4>
              <table className={`${isDark ? 'text-gray-200' : 'text-gray-800'} w-full`}>
                <tbody>
                  {payslip.otherPayables && Object.entries(payslip.otherPayables).map(([k,v]) => (
                    <tr key={k}><td>{k}</td><td className="text-right">{formatCurrency(v)}</td></tr>
                  ))}
                  <tr className="border-t pt-2"><td className="font-semibold">Total Other Payables</td><td className="text-right font-semibold">{formatCurrency(otherPayablesTotal)}</td></tr>
                </tbody>
              </table>
            </div>
            <div className={`${panelClass} p-4 rounded-md`}>
              <h4 className="font-semibold mb-2">Final Summary</h4>
              <table className={`${isDark ? 'text-gray-200' : 'text-gray-800'} w-full`}>
                <tbody>
                  <tr><td>Total Earnings</td><td className="text-right">{formatCurrency((gross || 0) + (payslip.adjustment || 0) + (totalAllowances || 0) + (payslip.breakdown?.serviceCredits || 0))}</td></tr>
                  <tr><td>Less: Deductions</td><td className="text-right">{formatCurrency(totalDeductions)}</td></tr>
                  <tr><td>Less: Other Payables</td><td className="text-right">{formatCurrency(otherPayablesTotal)}</td></tr>
                  <tr className="border-t pt-2"><td className="font-semibold">Net Pay</td><td className="text-right font-semibold">{formatCurrency(net)}</td></tr>
                </tbody>
              </table>
            </div>
          </div>

          <div className="flex justify-end space-x-3 mt-6 no-print">
            <button onClick={() => handleDownloadPayslip(payslip, 'excel')} className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg flex items-center space-x-2">
              <FileText className="h-4 w-4" />
              <span>Download Excel</span>
            </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};
 
